
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_18_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_18", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.209455182033143e+00, -5.108749512549251e+00, -4.967441893627056e+00, -4.771235714236027e+00, -4.502740612379207e+00, -4.142407714106445e+00, -3.670314535638282e+00, -3.066880977613848e+00, -2.312929690549299e+00, -1.458582254202504e+00, -8.121363072068997e-01, -6.074996266348874e-01, -6.347487130743100e-01, -5.478522295045306e-01, -3.611001608540873e-01, -1.816308543584614e-01, -7.413894872318356e-02, -2.402500204326271e-02, -5.139392031431472e-03, -5.779937739075585e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


